# c386: 산성 폭발 섬광 작지만 강하게 · 작은 좀비 더 밝게
C386_R = [('    for (const [col, s0, s1, life] of [[0xffffff, 0.8, R * 3.2, 0.16], [0xf2ffd0, 0.6, R * 2.2, 0.24]]) { const g = puff(x, 0.8, zz, col, s0, s1, life, 0, 0, 0, 1); g.s.renderOrder = UI - 0.6; g.peak = true; g.s.material.opacity = 1; }   // c385: 작은 섬광 (자폭 섬광보다 작고 짧게, 화면 번쩍 없음)', '    for (const [col, s0, s1, life] of [[0xffffff, 1.1, 2.0, 0.1], [0xf4ff6a, 0.7, 3.0, 0.17]]) { const g = puff(x, 0.8, zz, col, s0, s1, life, 0, 0, 0, 1); g.s.material.map = flashTex; g.s.renderOrder = UI - 0.55; g.peak = true; g.s.material.opacity = 1; }   // c386: 작지만 강한 섬광 — 터진 그 몸 자리에 또렷한 흰 원이 팍 (0.1초) + 노란 연두 원 (화면 번쩍 없음)\n    for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2 + rand(-0.2, 0.2), sp = rand(5, 8); const g = puff(x, 0.8, zz, i % 2 ? 0xffffff : 0xd8ff6a, 0.22, 0.08, 0.14, Math.cos(a) * sp, rand(0.5, 1.5), Math.sin(a) * sp, 1); g.s.material.map = flashTex; g.s.renderOrder = UI - 0.55; g.peak = true; }   // 사방으로 빠르게 튀는 불꽃 8개'), ('if (!c.mut) c.mesh.material.color.setHex(0xa1b6f7); }   /* c384: 작은 좀비 색 — 동료(0x8aa4f5)보다 20% 밝게 */', 'if (!c.mut) c.mesh.material.color.setHex(0xb9c8f9); }   /* c384 · c386: 작은 좀비 색 — 동료(0x8aa4f5)보다 40% 밝게 */')]
